CREATE TABLE cloud_sponsor_campaigns(id text PRIMARY KEY,title text NOT NULL,brief text NOT NULL,terms_version text NOT NULL,video_id text NOT NULL REFERENCES cloud_videos(id),source_id text NOT NULL UNIQUE REFERENCES cloud_reward_sources(id),budget_cents bigint NOT NULL CHECK(budget_cents>0),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,created_by text NOT NULL REFERENCES cloud_users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE cloud_sponsor_acceptances(campaign_id text PRIMARY KEY REFERENCES cloud_sponsor_campaigns(id),user_id text NOT NULL REFERENCES cloud_users(id),terms_version text NOT NULL,accepted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_sponsor_awards(id text PRIMARY KEY,campaign_id text NOT NULL REFERENCES cloud_sponsor_campaigns(id),cents bigint NOT NULL CHECK(cents>0),evidence_reference text NOT NULL,proposed_by text NOT NULL REFERENCES cloud_users(id),approved_by text REFERENCES cloud_users(id),approved_at timestamptz,batch_id text UNIQUE REFERENCES cloud_reward_batches(id),confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(approved_by IS NULL OR approved_by<>proposed_by));
ALTER TABLE cloud_watch_sessions ADD COLUMN traffic_source text NOT NULL DEFAULT 'unclassified' CHECK(traffic_source IN('organic','paid','unclassified'));
ALTER TABLE cloud_watch_sessions ADD COLUMN campaign_id text REFERENCES cloud_sponsor_campaigns(id);
ALTER TABLE cloud_watch_sessions ADD CONSTRAINT cloud_watch_paid_campaign CHECK((traffic_source='paid')=(campaign_id IS NOT NULL));
CREATE TRIGGER cloud_sponsor_campaign_immutable BEFORE UPDATE OR DELETE ON cloud_sponsor_campaigns FOR EACH ROW EXECUTE FUNCTION cloud_reward_immutable();
CREATE TRIGGER cloud_sponsor_acceptance_immutable BEFORE UPDATE OR DELETE ON cloud_sponsor_acceptances FOR EACH ROW EXECUTE FUNCTION cloud_reward_immutable();
